	dir := t.TempDir()
	body := "# Retry\n\nUse exponential backoff."
	writeMD(t, dir, "retry.md", body)

	h, store := docsHandler(t)
	cfg := sourceConfig{typ: "docs", path: dir}

	states, err := h.IngestEntityStates(context.Background(), cfg, testAuthority("acme"))
	if err != nil {
		t.Fatalf("IngestEntityStates() error: %v", err)
	}

	parents := parentStates(states)
	if len(parents) != 1 {
		t.Fatalf("parent state count: got %d, want 1 (retry.md); %d states in total", len(parents), len(states))
	}
	passages := passageStates(states)
	if len(passages) == 0 {
		t.Fatalf("passage state count: got 0, want at least 1 for retry.md; %d states in total", len(states))
	}

	assertBodyless(t, parents[0])

	referenced := make(map[string]bool)
	for _, passage := range passages {
		referenced[assertOffloadedBody(t, passage)] = true
	}
	if got := store.keys(); len(got) != len(referenced) {
		t.Fatalf("store blob count: got %d %v, want %d (one blob per distinct key a passage references, and nothing else)",
			len(got), got, len(referenced))
	}

	// The passage blobs tile the document: nothing is lost by the split.
	var joined strings.Builder
	for _, passage := range passages {
		joined.WriteString(passageBody(t, store, passage))
	}
	if joined.String() != body {
		t.Errorf("passage bodies concatenated = %q, want the document %q", joined.String(), body)
	}
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-75c46a.workspace.golang.function.handler-doc-handler_test-go-TestDocHandler_IngestEntityStates_BodyHandle"},{"name":"CodeBodyKey","kind":"const","path":"source/ast/predicates.go","lines":[78,78],"body":"	CodeBodyKey   = "code.body.key"   // storage key: the entity's body blob (content hash)","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.source-ast-predicates-go-CodeBodyKey"},{"name":"doc_body_storeregistry_integration_test.go","kind":"file","path":"internal/governance/doc_body_storeregistry_integration_test.go","lines":[1,262],"class":"http://www.ontologyrepository.com/CommonCoreOntologies/InformationBearingArtifact","handle":"c360.semsource-75c46a.workspace.golang.file.internal-governance-doc_body_storeregistry_integration_test-go"},{"name":"TestComponentStart_FailsWhenBodyStoreUnavailable","kind":"function","path":"processor/doc-source/body_store_test.go","lines":[62,74],"body":"func TestComponentStart_FailsWhenBodyStoreUnavailable(t *testing.T) {
