	counts := distinctSystems(members)
	var parts []string
	hidden := 0
	for _, s := range sortedByCount(counts) {
		share := 100 * float64(counts[s]) / float64(len(members))
		if share < 0.5 && len(parts) > 0 {
			hidden++
			continue
		}
		parts = append(parts, fmt.Sprintf("%s=%.0f%%", s, share))
	}
