	root := t.TempDir()
	write := func(rel, src string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(root, rel), []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("a.go", "package p\nfunc Alpha() {}\n")
	write("b.go", "package p\ntype M struct{}\nfunc (M) Beta() {}\n")
	write("c_test.go", "package p\nfunc TestOnly() {}\n")

	p := NewParser(testAuthority("acme"), "proj", root)
	funcs := p.packageFuncs(".")
	if funcs["Alpha"] != "a.go" {
		t.Errorf("funcs[Alpha] = %q, want a.go", funcs["Alpha"])
	}
	if _, ok := funcs["Beta"]; ok {
		t.Error("method Beta harvested as a package-level func")
	}
	if _, ok := funcs["TestOnly"]; ok {
		t.Error("_test.go func harvested")
	}

	// A sibling edit (size change) must invalidate the cached scan.
	write("b.go", "package p\ntype M struct{}\nfunc (M) Beta() {}\nfunc Gamma() {}\n")
	if got := p.packageFuncs(".")["Gamma"]; got != "b.go" {
		t.Errorf("after sibling edit, funcs[Gamma] = %q, want b.go", got)
	}
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-75c46a.workspace.golang.function.source-ast-golang-call_resolution_test-go-TestPackageScan_FuncsHarvested"},{"name":"OperationModify","kind":"const","path":"handler/types.go","lines":[89,89],"body":"	OperationModify ChangeOperation = "modify"","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.handler-types-go-OperationModify"},{"name":"upgradeUnrelatedSubject","kind":"const","path":"test/e2e/upgrade_path_test.go","lines":[32,32],"body":"	upgradeUnrelatedSubject = "unrelated.cutover.sentinel"","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.test-e2e-upgrade_path_test-go-upgradeUnrelatedSubject"},{"name":"IngestEntityStates","kind":"method","path":"handler/objectstore/handler.go","lines":[179,246],"body":"func (h *Handler) IngestEntityStates(ctx context.Context, cfg handler.SourceConfig) (*Result, error) {
	if err := h.authority.Validate(); err != nil {
		return nil, err
	}
	bucket, prefix, err := ParseSourceURL(cfg.GetURL())
	if err != nil {
		return nil, fmt.Errorf("objectstore handler: %w", err)
	}

	pass, err := Enumerate(ctx, h.store, prefix)
	if err != nil {
		return nil, err
	}

	previous := h.tracker.Observed()
	plan := pass.Plan(previous)
	system := h.System(bucket)
	now := time.Now().UTC()

	result := &Result{
		Skipped:   plan.Skipped,
		Unchanged: pass.Len() - len(plan.Fetch) - len(plan.Skipped),
		Bucket:    bucket,
		Prefix:    prefix,
	}

	for _, info := range plan.Fetch {
		if err := ctx.Err(); err != nil {
			return nil, err
		}

		states, err := h.ingestObject(ctx, info.Key, system, now)
		if err != nil {
			// An unreadable object is one document's problem: skip it and say
			// so. A body store that cannot be written to is the deployment's
			// problem, and every document after this one would fail the same
			// way — abort rather than report a healthy ingest of a corpus with
			// no retrievable bodies.
			if errors.Is(err, doc.ErrBodyStoreRequired) {
				return nil, err
			}
			result.Skipped = append(result.Skipped, Skip{Key: info.Key, Reason: SkipUnreadable})
			continue
		}

		operation := handler.OperationCreate
		if _, seen := previous[info.Key]; seen {
			operation = handler.OperationModify
		}

		token := ChangeToken(info)
		result.Ingested = append(result.Ingested, Ingested{
			Key:       info.Key,
			Token:     token,
			Operation: operation,
			States:    states,
		})
		h.tracker.Record(info.Key, token)
	}

	for _, key := range plan.Removed {
		result.Removed = append(result.Removed, Removal{
			Key:      key,
			EntityID: doc.DocumentEntityID(h.authority, system, key),
		})
	}
	return result, nil
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-75c46a.workspace.golang.method.handler-objectstore-handler-go-Handler-IngestEntityStates"},{"name":"pruneRetainedComponents","kind":"function","path":"cmd/semsource/config_drift.go","lines":[65,99],"body":"func pruneRetainedComponents(ctx context.Context, configMgr *semconfig.Manager, nc *natsclient.Client, declared semconfig.PlatformConfig, logger *slog.Logger) error {
	// The bucket is named by the declared pair, as the manager names it; the
	// effective platform id is the minted one.
	bucket, err := semconfig.BucketName(declared.Org, declared.ID)
	if err != nil {
		return fmt.Errorf("name the config bucket: %w", err)
	}
	reader, err := kvcatalog.OpenCatalogReader(ctx, nc, bucket)
	if err != nil {
		return fmt.Errorf("open config bucket %q to list components: %w", bucket, err)
	}
	keys, err := natsclient.FilteredKeys(ctx, reader, "components.*")
	if err != nil {
		return fmt.Errorf("list components in config bucket %q: %w", bucket, err)
	}
	// Start names every effective component as its key does, so the names
	// compare directly.
	effective := configMgr.GetConfig().Get().Components
	var removed []string
	for _, key := range keys {
		name := strings.TrimPrefix(key, "components.")
		if _, ok := effective[name]; ok {
			continue
		}
		if err := configMgr.DeleteComponentFromKV(ctx, name); err != nil {
			return fmt.Errorf("remove component %q, which the configuration file no longer defines, from config bucket %q: %w", name, bucket, err)
		}
		removed = append(removed, name)
	}
	if len(removed) > 0 {
		sort.Strings(removed)
		logger.Info(prunedComponentsMessage, "components", removed)
	}
	return nil
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-75c46a.workspace.golang.function.cmd-semsource-config_drift-go-pruneRetainedComponents"},{"name":"TestCompositionFingerprintMatchesGeneration","kind":"function","path":"cmd/semsource/composition_fingerprint_test.go","lines":[80,97],"body":"func TestCompositionFingerprintMatchesGeneration(t *testing.T) {
