	var drift configDrift
	appendDrift(&drift, "services", fromFile.Services, effective.Services, nil)
	disabled := map[string]bool{}
	for name, want := range fromFile.Components {
		if got, ok := effective.Components[name]; ok && want.Enabled && !got.Enabled {
			disabled[name] = true
			drift.retainedDisabled = append(drift.retainedDisabled, "components."+name)
		}
	}
	appendDrift(&drift, "components", fromFile.Components, effective.Components, disabled)
	if !sameDecodedJSON(fromFile.ModelRegistry, effective.ModelRegistry) {
		drift.differing = append(drift.differing, "model_registry")
	}
	if !sameDecodedJSON(fromFile.NATS, effective.NATS) {
		drift.differing = append(drift.differing, "nats")
	}
	sort.Strings(drift.differing)
	sort.Strings(drift.retainedOnly)
	sort.Strings(drift.retainedDisabled)
	return drift
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-75c46a.workspace.golang.function.cmd-semsource-config_drift-go-retainedConfigDrift"},{"name":"DocBodyKey","kind":"const","path":"source/vocabulary/predicates.go","lines":[52,52],"body":"	DocBodyKey   = "source.doc.body-key"   // storage key: the passage blob","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.source-vocabulary-predicates-go-DocBodyKey"},{"name":"DocChunkIndex","kind":"const","path":"source/vocabulary/predicates.go","lines":[31,31],"body":"	DocChunkIndex = "source.doc.chunk-index"","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.source-vocabulary-predicates-go-DocChunkIndex"},{"name":"TypeFile","kind":"const","path":"source/ast/predicates.go","lines":[105,105],"body":"	TypeFile      CodeEntityType = "file"","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.source-ast-predicates-go-TypeFile"},{"name":"DocChunkCount","kind":"const","path":"source/vocabulary/predicates.go","lines":[34,34],"body":"	DocChunkCount = "source.doc.chunk-count"","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.source-vocabulary-predicates-go-DocChunkCount"},{"name":"doc.go","kind":"file","path":"source/vocabulary/doc.go","lines":[1,64],"class":"http://www.ontologyrepository.com/CommonCoreOntologies/InformationBearingArtifact","handle":"c360.semsource-75c46a.workspace.golang.file.source-vocabulary-doc-go"},{"name":"orgFromRemote","kind":"function","path":"cli/detect.go","lines":[152,178],"body":"func orgFromRemote(remote string) string {
	// SSH format: git@host:org/repo.git
	if strings.Contains(remote, ":") && strings.Contains(remote, "@") {
		parts := strings.SplitN(remote, ":", 2)
		if len(parts) == 2 {
			path := strings.TrimSuffix(parts[1], ".git")
			segs := strings.Split(path, "/")
			if len(segs) >= 2 {
				return sanitizeName(segs[0])
			}
		}
	}

	// HTTPS format: https://host/org/repo.git
	remote = strings.TrimSuffix(remote, ".git")
	// Remove scheme.
	if idx := strings.Index(remote, "://"); idx >= 0 {
		remote = remote[idx+3:]
	}
	segs := strings.Split(remote, "/")
	// host/org/repo -> segs[1] is org
	if len(segs) >= 3 {
		return sanitizeName(segs[1])
	}

	return ""
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-75c46a.workspace.golang.function.cli-detect-go-orgFromRemote"},{"name":"TypeRepo","kind":"const","path":"source/ast/predicates.go","lines":[103,103],"body":"	TypeRepo      CodeEntityType = "repo"","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-75c46a.workspace.golang.const.source-ast-predicates-go-TypeRepo"},{"name":"adocHeading","kind":"function","path":"handler/doc/splitter.go","lines":[268,285],"body":"func adocHeading(lines []line, i int) (string, int, bool) {
	if lines[i].protected {
		return "", 0, false
	}
	t := strings.TrimSpace(lines[i].text)
	equals := 0
	for equals < len(t) && t[equals] == '=' {
		equals++
	}
	if equals == 0 || equals > 6 {
		return "", 0, false
	}
	rest := t[equals:]
	if !strings.HasPrefix(rest, " ") {
		return "", 0, false
	}
