	if err := authority.Validate(); err != nil {
		return nil, err
	}
	paths := resolvePaths(cfg)
	if len(paths) == 0 {
		return nil, fmt.Errorf("cfgfile: at least one path is required")
	}

	now := time.Now().UTC()
	var states []*handler.EntityState

	for _, root := range paths {
		err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			select {
			case <-ctx.Done():
				return ctx.Err()
			default:
			}
			if info.IsDir() {
				// Prune whole dependency trees rather than filtering their files
				// one by one: a node_modules walk yields thousands of package.json
				// files that are not this project's configuration.
				if handler.IsDefaultExcludedDir(info.Name()) {
					return filepath.SkipDir
				}
				if path != root && gitboundary.IsBoundary(path) {
					return filepath.SkipDir
				}
				return nil
			}
			base := filepath.Base(path)
			if !configFileNames[base] {
				return nil
			}

			content, readErr := os.ReadFile(path)
			if readErr != nil {
				h.logger.Warn("cfgfile: failed to read file", "path", path, "error", readErr)
				return nil
			}

			parsed := h.parseFileEntityStates(base, path, content, root, authority, now)
			states = append(states, parsed...)
			return nil
		})
		if err != nil && err != context.Canceled {
			return nil, fmt.Errorf("cfgfile: walk %s: %w", root, err)
		}
	}

	return states, nil
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-75c46a.workspace.golang.method.handler-cfgfile-handler-go-ConfigHandler-IngestEntityStates"},{"name":"newEntity","kind":"function","path":"handler/doc/entities.go","lines":[64,73],"body":"func newEntity(authority entityid.Authority, title, filePath, mimeType, contentHash, system string, indexedAt time.Time) *Entity {
